async function importLayout(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const payload=JSON.parse(await file.text());if(!payload||typeof payload!=='object'||!payload.config)throw Error('File denah tidak valid.');if(Number(payload.rows)!==current.rows.length)throw Error(`Jumlah plot berbeda: file ${payload.rows}, dataset ${current.rows.length}.`);if(!Array.isArray(payload.headers)||payload.headers.length!==current.headers.length||payload.headers.some((h,i)=>String(h)!==String(current.headers[i])))throw Error('Nama atau urutan kolom berbeda dengan dataset aktif.');const ids=current.rows.map((row,index)=>plotLabel(current,row,index).id);if(Array.isArray(payload.plotIds)&&(payload.plotIds.length!==ids.length||payload.plotIds.some((id,i)=>String(id)!==String(ids[i]))))throw Error('ID plot pada file denah tidak cocok dengan dataset aktif.');if(payload.dataset&&payload.dataset!==keyFor(current)&&!confirm(`Nama dataset berbeda (${payload.dataset}). Struktur dan ID plot cocok. Impor tetap dilanjutkan?`))return;const before=clone(config);config=normalizeConfig(current,payload.config);writeConfig(current,config);pushHistory('impor denah',before,[],config,[]);renderControls();renderMap();if(Number.isInteger(selectedRow))renderEditor(selectedRow);}catch(error){alert(error.message||'File denah tidak dapat dibaca.');}}
function resetLayout(){if(!confirm('Reset susunan fisik denah? Status, catatan, sesi, UID, foto, dan data plot tetap dipertahankan.'))return;const before=clone(config),base=defaultConfig(current);config={...config,columns:base.columns,serpentine:true,north:'N',roadEvery:0,order:{},spacers:{},flipX:false,flipY:false,zoom:1};commitConfig('reset susunan',before,{version:true});layoutEditMode=false;$('#fieldLayoutEdit')?.setAttribute('aria-pressed','false');renderControls();renderMap();}
function restoreLayoutVersion(){if(!config.versions.length){alert('Belum ada versi susunan sebelumnya.');return;}const list=config.versions.map((v,i)=>`${i+1}. ${new Date(v.at).toLocaleString('id-ID')} · ${v.reason}`).join('\n'),pick=prompt(`Pilih nomor versi yang akan dipulihkan:\n${list}`,String(config.versions.length));if(!pick)return;const version=config.versions[Number(pick)-1];if(!version)return alert('Nomor versi tidak valid.');const before=clone(config);config={...config,...clone(version.snapshot)};commitConfig('pulihkan versi denah',before,{version:true});renderControls();renderMap();}

function refreshData(render=true){current=dataset();const saved=readStore()[keyFor(current)];config=normalizeConfig(current,saved);writeConfig(current,config);if(render){renderControls();renderMap();}}
function closeFieldLayout({skipValidation=false}={}){if(dirty&&!saveEditor({quiet:true}))return;if(!skipValidation&&Number.isInteger(selectedRow)&&activeColumn()>=0){const group=groupLabelForRow(selectedRow),missing=current.rows.map((row,index)=>({row,index})).filter(x=>groupLabelForRow(x.index)===group&&!activeFilled(x.row));if(missing.length&&!confirm(`${group} masih memiliki ${missing.length} plot belum terisi untuk ${activeParameterName()}. Tutup denah?`))return;}revokePhotoUrls();$('#fieldLayoutModal')?.classList.remove('open','field-mode');document.body.classList.remove('field-layout-open');dirty=false;multiMode=false;layoutEditMode=false;fieldMode=false;selectedRows.clear();selectedRow=null;}
export function openFieldLayout(options={}){ensureModal();refreshData();$('#fieldLayoutDataset').textContent=`${current.name||'Dataset'} · ${current.rows.length} baris`;$('#fieldLayoutModal').classList.add('open');document.body.classList.add('field-layout-open');selectedRow=null;dirty=false;multiMode=false;layoutEditMode=false;fieldMode=false;selectedRows.clear();$('#fieldMultiToggle').setAttribute('aria-pressed','false');$('#fieldLayoutEdit').setAttribute('aria-pressed','false');$('#fieldModeToggle').setAttribute('aria-pressed','false');$('#fieldModeToggle').textContent='Field';$('#fieldPlotEditor').innerHTML='<div class="field-editor-empty">Klik satu plot untuk mengisi data.</div>';renderControls();renderMap();updateUndoButtons();const target=String(options.plotUid||new URLSearchParams(location.search).get('field_plot')||'');if(target){const row=rowByUid(target);if(row>=0)selectRow(row,{force:true,skipSave:true});}checkHandoff();}

// Public hook used by Result OS/outlier diagnostics and QR deep links.
globalThis.AgrotikFieldLayout={open:(options={})=>openFieldLayout(options),openPlot:identifier=>{ensureModal();refreshData(false);let row=rowByUid(String(identifier));if(row<0)row=current.rows.findIndex((r,i)=>plotLabel(current,r,i).id===String(identifier));openFieldLayout({plotUid:row>=0?plotUid(row):''});return row>=0;}};
